#[path="../setup/fast.rs"]mod fast;
use hec_native_ic::{counted,fp::Fp,jac::{Curve,Div},poly::Poly,rng::Rng};
fn probe(c:&Curve,d:&Div,t:&Div,ell:u64,sm:u64){let(fb,z,_)=fast::prepare(c);let mut map=vec![usize::MAX;fb.len()];let mut r=0;for j in 0..fb.len(){if map[j]!=usize::MAX{continue}assert_ne!(fb[j].0,0);let mut x=fb[j].0;for _ in 0..5{let k=fb.binary_search_by_key(&x,|p|p.0).unwrap();assert_eq!(map[k],usize::MAX);map[k]=r;x=c.fp.mul(x,z);}assert_eq!(x,fb[j].0);r+=1;}assert_eq!(fb.len(),5*r);assert!(!c.is_zero(d));assert!(c.is_zero(&c.mul(d,ell)));let mut anchor=*t;let mut rows=0;for a in 1..=16{anchor=c.add(&anchor,d);if anchor.u.deg()!=2{continue}let mut buckets=vec![vec![];c.fp.p as usize];for(j,&(x,y))in fb.iter().enumerate(){let u=anchor.u.eval(x,&c.fp);if u==0{continue}let inv=c.fp.inv(u);let v=anchor.v.eval(x,&c.fp);for yy in if y==0{vec![y]}else{vec![y,c.fp.neg(y)]}{let t=c.fp.mul(c.fp.sub(yy,v),inv);buckets[t as usize].push((j,yy));}}
for(t,b)in buckets.iter().enumerate(){if b.len()!=3{continue}let vt=anchor.v.add(&anchor.u.scale(t as u64,&c.fp),&c.fp);let h=c.f.sub(&vt.mul(&vt,&c.fp),&c.fp).div_exact(&anchor.u,&c.fp);assert_eq!(h.deg(),3);let mut reconstructed=Poly::one();let mut group=anchor;let mut support=vec![];let mut seen=std::collections::BTreeSet::new();for &(j,y)in b{let x=fb[j].0;assert!(seen.insert(x));assert_eq!(vt.eval(x,&c.fp),y);reconstructed=reconstructed.mul(&Poly::x_minus(x,&c.fp),&c.fp);group=c.add_place(&group,x,y);support.push(format!("{}:{x}:{y}",map[j]));}assert_eq!(h,reconstructed);assert!(c.is_zero(&group));println!("{}\t{sm}\t{r}\t{a}\t{t}\t{}",c.fp.p,support.join(","));rows+=1;}}
eprintln!("p={} sm={sm} orbit_columns={r} rows={rows} all_polynomial_and_original_group_checks=true",c.fp.p);}
fn main(){counted::disable();println!("p\tsm\torbit_columns\tanchor\tt\tsupport_orbit_x_y");for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let(fb,_,_)=fast::prepare(&c);let base=c.place(fb[0].0,fb[0].1);let mut rng=Rng::new(2026112500^p);for sm in [1,17]{let d=c.mul(&base,sm);let secret=1+rng.below(ell-1);let t=c.mul(&d,secret);eprintln!("fixture p={p} c={cc} ell={ell} sm={sm} source={d:?} target={t:?} qualification_scalar={secret}");probe(&c,&d,&t,ell,sm)}}eprintln!("fresh_workloads=6 anchors_per_workload=16 producer_complete=true no_speed_or_solve_claim=true");}
